# ---------------------------------------------------------------------------
# HELPERS
# ---------------------------------------------------------------------------

function Resolve-TargetPath {
    param([string]$Path)
    if ([System.IO.Path]::IsPathRooted($Path)) { return $Path }
    return Join-Path $PSScriptRoot $Path
}

# ---------------------------------------------------------------------------
# STEP 1 - DELETE REMOVED FILES
# ---------------------------------------------------------------------------

$delSuccess = 0; $delSkipped = 0; $delFailed = 0
Write-Host ""
Write-Host "Deleting $($FilesToDelete.Count) removed file(s)..." -ForegroundColor Cyan
Write-Host ("-" * 60)

foreach ($rel in $FilesToDelete) {
    $target = Resolve-TargetPath -Path $rel
    try {
        if (Test-Path $target) {
            Remove-Item -Path $target -Force
            Write-Host "  [DELETED] $rel" -ForegroundColor DarkYellow
            $delSuccess++
        } else {
            Write-Host "  [SKIP]    $rel (already gone)" -ForegroundColor DarkGray
            $delSkipped++
        }
    } catch {
        Write-Host "  [FAIL]    $rel - $_" -ForegroundColor Red
        $delFailed++
    }
}

# ---------------------------------------------------------------------------
# STEP 2 - WRITE MODIFIED / ADDED FILES
# ---------------------------------------------------------------------------

$writeSuccess = 0; $writeFailed = 0
Write-Host ""
Write-Host "Writing $($FilePatch.Count) file(s)..." -ForegroundColor Cyan
Write-Host ("-" * 60)

foreach ($patch in $FilePatch) {
    $targetPath = Resolve-TargetPath -Path $patch.Path
    try {
        $parentDir = Split-Path -Parent $targetPath
        if (-not (Test-Path $parentDir)) {
            New-Item -ItemType Directory -Path $parentDir -Force | Out-Null
        }
        $bytes = [Convert]::FromBase64String($patch.Content)
        [System.IO.File]::WriteAllBytes($targetPath, $bytes)
        Write-Host "  [OK]   $($patch.Path)" -ForegroundColor Green
        $writeSuccess++
    } catch {
        Write-Host "  [FAIL] $($patch.Path) - $_" -ForegroundColor Red
        $writeFailed++
    }
}

# ---------------------------------------------------------------------------
# SUMMARY
# ---------------------------------------------------------------------------

Write-Host ""
Write-Host ("-" * 60)
Write-Host "Deletions : $delSuccess deleted, $delSkipped skipped, $delFailed failed" -ForegroundColor $(if ($delFailed -gt 0) { "Yellow" } else { "Cyan" })
Write-Host "Writes    : $writeSuccess succeeded, $writeFailed failed"               -ForegroundColor $(if ($writeFailed -gt 0) { "Yellow" } else { "Cyan" })
Write-Host ""